class Solution {
public:
    bool wordPattern(string pattern, string s) {
        vector<string> words;
        stringstream ss(s);
        string w;
        while (ss >> w) words.push_back(w);
        if (pattern.size() != words.size()) return false;
        unordered_map<char, string> p2w;
        unordered_map<string, char> w2p;
        for (size_t i = 0; i < pattern.size(); ++i) {
            char c = pattern[i];
            string word = words[i];
            if (p2w.count(c) && p2w[c] != word) return false;
            if (w2p.count(word) && w2p[word] != c) return false;
            p2w[c] = word;
            w2p[word] = c;
        }
        return true;
    }
};

class Solution {
    public boolean wordPattern(String pattern, String s) {
        String[] words = s.split(" ");
        if (pattern.length() != words.length) return false;
        Map<Character, String> p2w = new HashMap<>();
        Map<String, Character> w2p = new HashMap<>();
        for (int i = 0; i < pattern.length(); i++) {
            char c = pattern.charAt(i);
            String w = words[i];
            if (p2w.containsKey(c) && !p2w.get(c).equals(w)) return false;
            if (w2p.containsKey(w) && w2p.get(w) != c) return false;
            p2w.put(c, w);
            w2p.put(w, c);
        }
        return true;
    }
}

