var wordPattern = function(pattern, s) {
    const words = s.split(" ");
    if (pattern.length !== words.length) return false;
    const p2w = new Map();
    const w2p = new Map();
    for (let i = 0; i < pattern.length; i++) {
        const c = pattern[i];
        const w = words[i];
        if (p2w.has(c) && p2w.get(c) !== w) return false;
        if (w2p.has(w) && w2p.get(w) !== c) return false;
        p2w.set(c, w);
        w2p.set(w, c);
    }
    return true;
};
